      .filter(Boolean)
      .some((value) => String(value).toLowerCase().includes(normalizedQuery));
  }), [profiles, blockedIds, normalizedQuery]);
  const blockedProfiles = useMemo(() => profiles.filter((profile) => blockedIds.has(profile.id)), [profiles, blockedIds]);

